function seaScene(id, k) { return `<rect width="1000" height="1000" fill="#0e1736"/><circle cx="500" cy="260" r="90" fill="#fff4d6" opacity=".9"/><circle cx="500" cy="260" r="200" fill="#fff4d6" opacity=".1"/><rect y="520" width="1000" height="480" fill="#122a5a"/>${Array.from({ length: 9 }, (_, i) => `<path d="M0 ${560 + i * 52} q125 -22 250 0 t250 0 t250 0 t250 0" stroke="#bcd8ff" stroke-opacity="${0.5 - i * 0.04}" stroke-width="5" fill="none"/>`).join("")}<path d="M440 520 L560 520 L640 1000 L360 1000z" fill="#fff4d6" opacity=".16"/><path d="M0 900 q250 -60 500 0 t500 -20 V1000 H0z" fill="#d9c39a" opacity=".85"/>`; }
function mountScene(id, k) { return `<rect width="1000" height="1000" fill="#0f1738"/>${Array.from({ length: 60 }, (_, i) => `<circle cx="${(i * 137) % 1000}" cy="${(i * 71) % 480}" r="${1 + (i % 3)}" fill="#fff" opacity=".7"/>`).join("")}<path d="M0 760 L200 380 L340 560 L520 260 L720 560 L860 420 L1000 700 V1000 H0z" fill="#1c2a5c"/><path d="M520 260 L460 380 L520 350 L580 400Z" fill="#e8f0ff" opacity=".9"/><path d="M200 380 L160 460 L210 440 L250 470Z" fill="#e8f0ff" opacity=".8"/><path d="M0 800 L1000 740 V1000 H0z" fill="#12204a"/><path d="M520 790 C480 860 600 900 540 1000" stroke="#9fd0ff" stroke-width="34" fill="none" opacity=".8"/><path d="M520 790 C480 860 600 900 540 1000" stroke="#fff" stroke-width="8" fill="none" opacity=".6"/>`; }
const dioN = (id, scene, cx, cy, r, k) => `<g>${porthole(id, cx, cy, r, `<g transform="translate(${cx - r} ${cy - r}) scale(${(2 * r) / 1000})">${scene(id, k)}</g>`, k).replace(/#2a3358|#4a5584|#1b2142/g, "#0d0f2a")}<circle cx="${cx}" cy="${cy}" r="${r + 36}" fill="none" stroke="url(#${id}-gNeon)" stroke-width="9" filter="url(#${id}-fGlowN)"/></g>`;
