// ---------- minutage estimé (0,34 s par mot) + respirations ----------
let t = 0.1;
for (const f of F) { f.t0 = t; t += f.words * 0.34 + (f.pause || 0); f.t1 = t; t += 0.2; }
const total = t;
const fmt = (x) => x.toFixed(1).replace(".", ",");
const totalWords = F.reduce((a, f) => a + f.words, 0);

function render(id, world, hud) {
  const root = { innerHTML: "", querySelector: () => null, querySelectorAll: () => [] };
  L.stage(root, id, world.replaceAll("ID-", id + "-"), hud.replaceAll("ID-", id + "-"));
  return root.innerHTML.replace(/<rect id="[^"]*-lid[LR]"[^>]*\/>/g, "").replace(/<rect id="[^"]*-screenOff"[^>]*\/>/g, "").replace(/<circle id="[^"]*-(seed|ring)"[^>]*\/>/g, "");
}
const cell = (f) => {
  const A = L.art(f.id + "-");
  const b = f.build(A, f.id);
  const svg = render(f.id, b.world.replaceAll(`${f.id}-`, "ID-"), (b.hud || "").replaceAll(`${f.id}-`, "ID-"));
  return `<article class="cell" id="frame-${f.id.slice(1)}">
  <div class="frame">${svg}<svg class="safe" viewBox="0 0 1080 1920" xmlns="http://www.w3.org/2000/svg"><g opacity=".6" fill="none" stroke="#ff6b6b" stroke-width="3" stroke-dasharray="14 10"><rect x="920" y="780" width="150" height="740"/><rect x="0" y="1530" width="1080" height="390"/><rect x="0" y="0" width="1080" height="150"/></g></svg></div>
  <div class="label"><span>${f.id.slice(1)} · ${f.name}</span><span>≈ ${fmt(f.t0)}–${fmt(f.t1)} s</span></div>
  <p class="voice">« ${f.voice} »</p>
  <p class="note">${f.note}</p>
  <div class="chips"><span class="chip">→ ${f.seam}</span><span class="chip tag">${f.tag}</span></div>
</article>`;
};

const principles = `<article class="cell meta wide"><h3>Principes (la même direction que « Astronaute »)</h3><ol class="seams">
<li><b>Décors immersifs, pas minimalistes.</b> La grotte (roche mouillée, stalactites, cristaux, brume, gouttes) et le grenier (poutres en perspective, lames de lumière, poussière) sont dessinés avec trois plans de profondeur et des objets en suspension. Une seule vue large par décor.</li>
<li><b>Deux températures.</b> Froid de la grotte (bleu-violet) contre chaud du grenier et de ta chambre (ambre) ; le néon (cyan → violet → magenta) n'arrive qu'à « Sur Listen » (15-16).</li>
<li><b>La chauve-souris est un vrai personnage</b> dans la DA : corps rond, ailes enroulées en cape, yeux fermés, visage vu à l'envers (le gag « tête en bas »). Même structure que « Astronaute » : badges 1, 2, 3 pour les « nouvelles », même lit en ouverture et en fermeture, même carte de fin. La boucle revient sur le lit qui se retourne.</li>
<li><b>Les instruments répondent</b> à ceux d'« Astronaute » : le cadran de 24 h (16-20 h) fait écho au cadran des 16 levers de soleil ; les ondes pâles de la chauve-souris (écholocation) préparent les ondes néon du téléphone.</li>
<li><b>Aucun raccord sur le même cadrage</b> (leçon de « Dessous ») : les plans 02-03-05 sont le même lieu en caméra mobile ; 14 → 15 → 16 est un seul geste de néon.</li></ol></article>`;
const questions = `<article class="cell meta"><h3>À trancher avant la voix</h3><ol class="seams">
<li><b>Le gag « tu resterais accroché » (05)</b> : fantôme de dessin animé qui s'élève pendant que le corps reste accroché. Si c'est trop, je garde juste « elle reste accrochée ».</li>
<li><b>Faits</b> : tout est exact (verrou des tendons des pattes ; torpeur jusqu'à la température de la grotte ; hibernation de 5-6 mois chez certaines espèces tempérées ; 16-20 h de sommeil pour la plupart). « Elle voit le monde avec ses oreilles » est une image : certaines (grandes roussettes) ne s'écholocalisent pas, mais « la plupart » le font ; ce n'est pas une erreur du script.</li>
<li><b>La part de Listen</b> : ≈ 44 mots sur ≈ 142, soit près du tiers. C'est plus que « Astronaute ». « Pour te détendre ou changer d'air » est la promesse la plus forte (allégation « détente », point ouvert de la série) : à toi de voir si on l'adoucit. Je ne touche pas à ton texte.</li>
<li><b>Les trois lieux néon</b> (forêt la nuit, bord de mer, montagne) sont mes propositions : les noms réels des pistes de l'appli ne sont pas vérifiés.</li>
<li><b>Voix</b> : Clément (comme « Astronaute ») ? Tu me donnes voix + SRT. Durée estimée ≈ ${Math.round(total)} s (0,34 s par mot) ; ta prise fera foi.</li></ol></article>`;

